input.code:
const dsl = `workspace "Bank Portal" "C4 model of the online banking platform" {

    !identifiers hierarchical

    model {

        customer = person "Bank Customer" "A customer of the bank who manages accounts, moves money, and tracks activity"

        bankPortal = softwareSystem "Bank Portal" "Online banking platform for managing accounts, moving money, and tracking activity" {

            webPortal = container "Web Portal" "Where customers log in and manage their accounts"
            mobileBackend = container "Mobile App Backend" "Serves the bank's mobile app"
            accountService = container "Account Service" "Holds the customer account records"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers"
            paymentService = container "Payment Service" "Executes card payments and bank transfers"
            cardService = container "Card Service" "Manages debit and credit cards"
            fraudDetection = container "Fraud Detection Service" "Scores transactions for fraud"
            notificationService = container "Notification Service" "Sends email and SMS alerts"
            onboardingService = container "Onboarding Service" "Verifies new customers"
            statementsService = container "Statements Service" "Generates monthly statements"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation"
            eventQueue = container "Event Queue" "Carries internal events between the application parts" "Queue"
            ledgerDb = container "Ledger Database" "Stores every account movement" "Database"
            customerDb = container "Customer Database" "Stores account and profile records" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Database"
            cache = container "Cache" "Stores sessions and frequently read account data"
            documentStore = container "Document Store" "Holds the generated statement PDFs"
        }

        cardNetwork = softwareSystem "Card Payment Network" "Card payment network operated by a different organization" "External"
        creditAgency = softwareSystem "Credit Reference Agency" "Credit reference agency operated by a different organization" "External"

        customer -> bankPortal.webPortal "logs in and manages accounts, moves money, and tracks activity"
        customer -> bankPortal.mobileBackend "uses the bank's mobile app to manage accounts, move money, and track activity"

        bankPortal.webPortal -> bankPortal.accountService "manages accounts"
        bankPortal.webPortal -> bankPortal.transactionService "submits deposits, withdrawals, and transfers"
        bankPortal.webPortal -> bankPortal.paymentService "requests card payments and bank transfers"
        bankPortal.webPortal -> bankPortal.cardService "manages debit and credit cards"
        bankPortal.webPortal -> bankPortal.statementsService "requests monthly statements"
        bankPortal.webPortal -> bankPortal.directDebitService "manages standing orders and direct debits"

        bankPortal.mobileBackend -> bankPortal.accountService "manages accounts"
        bankPortal.mobileBackend -> bankPortal.transactionService "submits deposits, withdrawals, and transfers"
        bankPortal.mobileBackend -> bankPortal.paymentService "requests card payments and bank transfers"
        bankPortal.mobileBackend -> bankPortal.cardService "manages debit and credit cards"
        bankPortal.mobileBackend -> bankPortal.statementsService "requests monthly statements"
        bankPortal.mobileBackend -> bankPortal.directDebitService "manages standing orders and direct debits"

        bankPortal.paymentService -> cardNetwork "routes card authorisations through"
        bankPortal.onboardingService -> creditAgency "performs credit checks through"

        bankPortal.transactionService -> bankPortal.ledgerDb "updates"
        bankPortal.transactionService -> bankPortal.fraudDetection "scores transactions with"
        bankPortal.transactionService -> bankPortal.eventQueue "publishes events to"

        bankPortal.notificationService -> bankPortal.eventQueue "consumes events from"
        bankPortal.statementsService -> bankPortal.ledgerDb "reads"
        bankPortal.statementsService -> bankPortal.documentStore "writes"
        bankPortal.batchScheduler -> bankPortal.ledgerDb "reads and writes"
        bankPortal.batchScheduler -> bankPortal.customerDb "reads and writes"

        bankPortal.cardService -> bankPortal.paymentService "serves"
        bankPortal.exchangeRatesService -> bankPortal.paymentService "serves"
        bankPortal.onboardingService -> bankPortal.customerDb "reads"
    }

    views {

        systemContext bankPortal "SystemContext" {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" {
            include *
            autoLayout
            title "Container Diagram for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
        }
    }
}`;

const [parse, validate, inspect] = await Promise.allSettled([
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);

function fmt(r) {
  if (r.status === "rejected") return { error: String(r.reason) };
  return r.value;
}
return { parse: fmt(parse), validate: fmt(validate), inspect: fmt(inspect) };

